import type { Metadata } from 'next'
import Link from 'next/link'
import { notFound } from 'next/navigation'
import type { Comment, Post } from '../../../lib/types'

interface BlogPostPageProps {
  params: Promise<{ id: string }>
}

export const revalidate = 300

async function getPost(id: string): Promise<{ post: Post; comments: Comment[] } | null> {
  try {
    const [postRes, commentsRes] = await Promise.all([
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}`),
      fetch(`https://jsonplaceholder.typicode.com/posts/${id}/comments`),
    ])

    if (!postRes.ok) {
      return null
    }

    const post: Post = await postRes.json()
    const comments: Comment[] = await commentsRes.json()

    return { post, comments }
  } catch {
    return null
  }
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  const data = await getPost(id)

  if (!data) {
    return {
      title: 'Post Not Found - My Blog',
    }
  }

  const { post } = data
  const description = post.body.substring(0, 160)

  return {
    title: `${post.title} - My Blog`,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params
  const data = await getPost(id)

  if (!data) {
    notFound()
  }

  const { post, comments } = data

  return (
    <article>
      <Link href="/blog">
        <button>← Back</button>
      </Link>

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}

